      "manuscript_directory": "results/manuscript"
    }
  },
  "search_terms": {
    "project": {
      "id": "sglt2_inhibitors_cardiac_surgery",
      "title": "Efficacy and safety of preoperative or perioperative SGLT2 inhibitors in adult cardiac surgery: a systematic review and meta-analysis",
      "short_name": "sglt2i_card_surg"
    },
    "search": {
      "concepts": [
        {
          "concept_id": "population",
          "label": "Adult patients undergoing open cardiac surgery",
          "role": "population",
          "required": true,
          "free_text_terms": [
            "cardiac surgery",
            "heart surgery",
            "open-heart surgery",
            "coronary artery bypass",
            "coronary artery bypass grafting",
            "coronary bypass",
            "CABG",
            "valve surgery",
            "valve replacement",
            "valvular surgery",
            "aortic surgery",
            "aortic root replacement",
            "aortic arch surgery"
          ],
          "abbreviations": [
            "CABG"
          ],
          "spelling_variants": [
            "open heart surgery",
            "valvular operation",
            "coronary by-pass"
          ],
          "controlled_vocabulary": {
            "pubmed_mesh_candidates": [
              "Cardiac Surgical Procedures",
              "Coronary Artery Bypass",
              "Heart Valve Prosthesis Implantation",
              "Aortic Aneurysm, Thoracic"
            ],
            "embase_emtree_candidates": [
              "heart surgery",
              "coronary artery bypass graft",
              "heart valve replacement",
              "aorta surgery"
            ]
          }
        },
        {
          "concept_id": "intervention",
          "label": "SGLT2 inhibitors (gliflozins), preoperative or perioperative exposure",
          "role": "intervention",
          "required": true,
          "free_text_terms": [
            "sodium-glucose cotransporter 2 inhibitor",
            "sodium-glucose co-transporter 2 inhibitor",
            "sglt2 inhibitor",
            "gliflozin",
            "dapagliflozin",
            "empagliflozin",
            "canagliflozin",
            "ertugliflozin",
            "ipragliflozin"
          ],
          "abbreviations": [
            "SGLT2",
            "SGLT2i"
          ],
          "spelling_variants": [
            "sodium glucose cotransporter 2 inhibitor",
            "sodium glucose co-transporter 2 inhibitor",
            "co transporter 2"
          ],
          "controlled_vocabulary": {
            "pubmed_mesh_candidates": [
              "Sodium-Glucose Transporter 2 Inhibitors",
              "Dapagliflozin",
              "Empagliflozin",
              "Canagliflozin",
              "Ertugliflozin"
            ],
            "embase_emtree_candidates": [
              "sodium glucose cotransporter 2 inhibitor",
              "dapagliflozin",
              "empagliflozin",
              "canagliflozin",
              "ertugliflozin"
            ]
          }
        }
      ],
      "combination": {
        "operator_between_concepts": "AND",
        "notes": "Population specifies open cardiac surgical procedures to anchor the perioperative window. Outcomes are intentionally omitted from search concepts to maintain recall; they will be applied during screening."
      },
      "outcome_terms_policy": "Do not include outcomes as mandatory search concepts; screen for outcomes during study selection to preserve sensitivity."
    },
    "validation": {
      "known_relevant_ids": [],
      "controlled_vocabulary_requires_verification": true
    }
  },
  "human_decisions_required": [
    {
      "decision_id": "D01_transcatheter_scope",
      "question": "Should transcatheter-only cardiac procedures (e.g., TAVR/TAVI, MitraClip, PCI) be included as eligible populations?",
      "why_it_matters": "Including transcatheter procedures broadens the population beyond open cardiac surgery and may change risk profiles and perioperative management, affecting applicability and heterogeneity.",
      "suggested_options": [
        "exclude_transcatheter_only",
        "include_transcatheter_only"
      ],
      "recommended_option": "exclude_transcatheter_only",
      "recommendation_rationale": "The review is targeted to open surgical cardiac procedures; transcatheter interventions are procedurally and perioperatively distinct.",
      "affected_components": [
        "project_config.eligibility",
        "project_config.screening"
      ],
      "option_patches": [
        {
          "option": "exclude_transcatheter_only",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "exclusion"
              ],
              "operation": "append_unique",
              "value_json": "\"Transcatheter-only cardiac procedures (e.g., TAVR/TAVI, MitraClip, PCI)\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Ensure explicit exclusion remains in scope definition."
            }
          ]
        },
        {
          "option": "include_transcatheter_only",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "exclusion"
              ],
              "operation": "remove_value",
              "value_json": "\"Transcatheter-only cardiac procedures (e.g., TAVR/TAVI, MitraClip, PCI)\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Remove exclusion to allow transcatheter populations."
            },
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "inclusion"
              ],
              "operation": "append_unique",
              "value_json": "\"Transcatheter cardiac procedures (e.g., TAVR/TAVI, MitraClip, PCI) are eligible\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Clarify broadened population in inclusion criteria."
            }
          ]
        }
      ]
    },
    {
      "decision_id": "D02_heart_transplant_scope",
      "question": "Should heart transplantation procedures be included as eligible cardiac surgery?",
      "why_it_matters": "Heart transplantation patients have unique perioperative and immunosuppressive considerations that may affect safety and efficacy outcomes.",
      "suggested_options": [
        "exclude_heart_transplant",
        "include_heart_transplant"
      ],
      "recommended_option": "exclude_heart_transplant",
      "recommendation_rationale": "Maintains a more homogeneous surgical population aligned with typical cardiac surgery cohorts (CABG/valve/aortic).",
      "affected_components": [
        "project_config.eligibility"
      ],
      "option_patches": [
        {
          "option": "exclude_heart_transplant",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "exclusion"
              ],
              "operation": "append_unique",
              "value_json": "\"Heart transplantation surgery\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Keep transplant procedures outside current scope."
            }
          ]
        },
        {
          "option": "include_heart_transplant",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "exclusion"
              ],
              "operation": "remove_value",
              "value_json": "\"Heart transplantation surgery\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Permit inclusion of transplant cohorts."
            },
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "inclusion"
              ],
              "operation": "append_unique",
              "value_json": "\"Heart transplantation procedures are eligible\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Record scope expansion explicitly."
            }
          ]
        }
      ]
    },
    {
      "decision_id": "D03_vad_scope",
      "question": "Should ventricular assist device (VAD) implantation procedures be included as eligible cardiac surgery?",
      "why_it_matters": "VAD implantation has distinct perioperative risks and patient characteristics that may alter intervention effects and safety outcomes.",
      "suggested_options": [
        "exclude_vad",
        "include_vad"
      ],
      "recommended_option": "exclude_vad",
      "recommendation_rationale": "Preserves homogeneity with conventional open cardiac surgeries (CABG/valve/aortic).",
      "affected_components": [
        "project_config.eligibility"
      ],
      "option_patches": [
        {
          "option": "exclude_vad",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "exclusion"
              ],
              "operation": "append_unique",
              "value_json": "\"Ventricular assist device implantation\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Keep VAD procedures outside current scope."
            }
          ]
        },
        {
          "option": "include_vad",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "exclusion"
              ],
              "operation": "remove_value",
              "value_json": "\"Ventricular assist device implantation\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Permit inclusion of VAD implantation cohorts."
            },
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "inclusion"
              ],
              "operation": "append_unique",
              "value_json": "\"Ventricular assist device implantation procedures are eligible\"",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Record scope expansion explicitly."
            }
          ]
        }
      ]
    },
    {
      "decision_id": "D04_conference_abstracts",
      "question": "Should conference abstracts without full-text articles be included?",
      "why_it_matters": "Including abstracts can increase recall but may introduce incomplete data and risk of bias; exclusion may omit recent evidence.",
      "suggested_options": [
        "exclude_conference_abstracts",
        "include_conference_abstracts"
      ],
      "recommended_option": "exclude_conference_abstracts",
      "recommendation_rationale": "Conservative default prioritizes data completeness and quality.",
      "affected_components": [
        "project_config.eligibility.publication_status",
        "project_config.screening"
      ],
      "option_patches": [
        {
          "option": "exclude_conference_abstracts",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "publication_status",
                "include_conference_abstracts"
              ],
              "operation": "set",
              "value_json": "false",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Maintain exclusion of abstracts for data quality."
            }
          ]
        },
        {
          "option": "include_conference_abstracts",
          "operations": [
            {
              "target": "project_config",
              "path": [
                "eligibility",
                "publication_status",
                "include_conference_abstracts"
              ],
              "operation": "set",
              "value_json": "true",
              "match_key": "",
              "match_value_json": "",
              "rationale": "Permit inclusion of abstracts to maximize recall."
            }
          ]
        }
      ]
    }
  ],
  "report": {
    "summary": "Initialized a PICOS-framed systematic review and meta-analysis on SGLT2 inhibitor exposure in adult cardiac surgery, with conservative eligibility (open surgical procedures; comparative designs; peer-reviewed full texts), comprehensive search databases, and concept-based, outcome-agnostic search terms. Material scope decisions regarding transcatheter procedures, heart transplantation, VAD implantation, and conference abstracts are flagged for human confirmation with deterministic patches.",
    "assumptions": [
      "Adults (≥18 years) only; pediatric studies are excluded.",
      "Cardiac surgery refers to open surgical procedures (CABG, valve, aortic) by default.",
      "Preoperative/perioperative exposure window includes pre-admission or chronic outpatient use carried into the preoperative period and exposure during the index hospitalization up to surgery and immediate postoperative period.",
      "Comparative study designs are required (RCTs and comparative cohorts); non-comparative studies and case series are excluded without separate decision.",
      "Language has no restrictions; studies in any language are eligible if otherwise includable.",
      "Peer-reviewed full texts included; preprints excluded by default due to uncertain peer-review status.",
      "Conference abstracts are excluded by default but surfaced for decision.",
      "Dual SGLT1/2 inhibitors (e.g., sotagliflozin) are not considered SGLT2 inhibitors and would be excluded unless SGLT2-specific effects are separable.",
      "Outcome terms are not included in the search strategy to preserve sensitivity; outcomes will be applied at screening and extraction."
    ],
    "warnings": [
      "Candidate controlled-vocabulary terms require librarian verification and possible refinement before finalizing database-specific strategies.",
      "The term mapping for aortic procedures may need adjustment (e.g., specific MeSH/Emtree headings for aortic root or arch surgery).",
      "Exposure timing (preoperative vs perioperative) is often poorly indexed and may rely on full-text assessment during screening.",
      "If scope decisions (transcatheter, transplant, VAD, abstracts) change, apply the provided patches before generating search strategies and screening workbooks."
    ]
  }
}
